const today = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; };
const dateOf = (date: string) => new Date(`${date}T12:00:00`);
const localMotto = () => { const key = today().replaceAll('-', '').split('').reduce((sum, n) => sum + Number(n), 0); return MOTTOS[key % MOTTOS.length]; };
const notifiedReminderOccurrences = new Set<string>();
const greetingFor = (name: string, hour = new Date().getHours()) => `${hour < 12 ? 'Good morning' : hour < 18 ? 'Good afternoon' : 'Good evening'}${name.trim() ? `, ${name.trim()}` : ''}.`;
const monthText = (value?: string) => value ? new Date(`${value}-01T12:00:00`).toLocaleDateString(undefined, { month: 'short', year: 'numeric' }) : 'No date';
const downloadCSV = (transactions: Transaction[], currency: Currency) => {
  const columns = ['ID', 'Date', 'Description', 'Type', 'Amount', 'Category', 'Payment method', 'Notes'];
  const escape = (v: string | number) => { const text = String(v); const safe = /^[=+\-@\t\r]/.test(text) ? `'${text}` : text; return `"${safe.replaceAll('"', '""')}"`; };
  const rows = transactions.map(t => [t.id, t.date, t.description, t.type, (t.amountMinor / (10 ** digitsFor(currency))).toFixed(digitsFor(currency)), t.category, t.paymentMethod ?? '', t.notes ?? '']);
  downloadFile(`ledgerly-transactions-${today()}.csv`, [columns, ...rows].map(row => row.map(escape).join(',')).join('\r\n'), 'text/csv;charset=utf-8');
};
const amountInput = (minor: number | undefined, currency: Currency) => minor === undefined ? '' : (minor / (10 ** digitsFor(currency))).toFixed(digitsFor(currency));

function ModalShell({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const modalRef = useRef<HTMLElement>(null);
  useEffect(() => {
    const previousFocus = document.activeElement as HTMLElement | null; const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden'; modalRef.current?.querySelector<HTMLElement>('input,select,button,textarea,[tabindex]:not([tabindex="-1"])')?.focus();
    const key = (e: KeyboardEvent) => {
      if (e.key === 'Escape') { onClose(); return; }
      if (e.key === 'Tab' && modalRef.current) { const focusable = [...modalRef.current.querySelectorAll<HTMLElement>('input,select,button,textarea,[tabindex]:not([tabindex="-1"])')].filter(el => !el.hasAttribute('disabled')); const first = focusable[0]; const last = focusable.at(-1); if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); } else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); } }
    };
    window.addEventListener('keydown', key); return () => { window.removeEventListener('keydown', key); document.body.style.overflow = previousOverflow; if (previousFocus?.isConnected) previousFocus.focus(); };
  }, [onClose]);
  return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><section ref={modalRef} className={`modal ${wide ? 'modal-wide' : ''}`} role="dialog" aria-modal="true" aria-labelledby="modal-title"><header className="modal-head"><div><p className="eyebrow">LEDGERLY</p><h2 id="modal-title">{title}</h2></div><button className="icon-button" onClick={onClose} aria-label="Close"><X size={19}/></button></header>{children}</section></div>;
}
function TextField({ label, value, onChange, type = 'text', required = false, placeholder, min, max, step, hint }: { label: string; value: string | number; onChange: (v: string) => void; type?: string; required?: boolean; placeholder?: string; min?: string | number; max?: string | number; step?: string | number; hint?: string }) {
  return <label className="field"><span>{label}{required && <b className="required"> *</b>}</span><input type={type} value={value} onChange={e => onChange(e.target.value)} required={required} placeholder={placeholder} min={min} max={max} step={step}/>{hint && <small>{hint}</small>}</label>;
}
function SelectField({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (v: string) => void }) {
  return <label className="field"><span>{label}</span><select value={value} onChange={e => onChange(e.target.value)}>{options.map(option => <option key={option} value={option}>{option}</option>)}</select></label>;
}
function TransactionForm({ initial, currency, onSave, onCancel }: { initial?: Transaction; currency: Currency; onSave: (t: Transaction) => boolean; onCancel: () => void }) {
  const [type, setType] = useState(initial?.type ?? 'expense'); const [description, setDescription] = useState(initial?.description ?? ''); const [amount, setAmount] = useState(amountInput(initial?.amountMinor, currency));
  const [category, setCategory] = useState(initial?.category ?? EXPENSE_CATEGORIES[0]); const [date, setDate] = useState(initial?.date ?? today()); const [payment, setPayment] = useState(initial?.paymentMethod ?? ''); const [notes, setNotes] = useState(initial?.notes ?? ''); const [error, setError] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); try { if (!description.trim()) throw new Error('Add a short description.'); const amountMinor = toMinor(amount, currency); const now = new Date().toISOString(); const saved = onSave({ id: initial?.id ?? uid(), description: description.trim(), type, amountMinor, category, date, paymentMethod: payment.trim() || undefined, notes: notes.trim() || undefined, createdAt: initial?.createdAt ?? now, updatedAt: now }); if (saved) onCancel(); } catch (e) { setError(e instanceof Error ? e.message : 'Check the form and try again.'); } };
  return <form className="form" onSubmit={submit}><div className="segmented"><button type="button" className={type === 'expense' ? 'selected expense-choice' : ''} onClick={() => { setType('expense'); setCategory(EXPENSE_CATEGORIES[0]); }}>Expense</button><button type="button" className={type === 'income' ? 'selected income-choice' : ''} onClick={() => { setType('income'); setCategory(INCOME_CATEGORIES[0]); }}>Income</button></div>
    <TextField label="Description" value={description} onChange={setDescription} required placeholder={type === 'expense' ? 'e.g. Weekly groceries' : 'e.g. Monthly salary'}/>
    <div className="form-grid"><TextField label={`Amount (${currency})`} value={amount} onChange={setAmount} type="number" required min="0" step={digitsFor(currency) ? String(1 / (10 ** digitsFor(currency))) : '1'} placeholder="0.00"/><TextField label="Date" value={date} onChange={setDate} type="date" required/></div>
    <SelectField label="Category" value={category} options={type === 'income' ? INCOME_CATEGORIES : EXPENSE_CATEGORIES} onChange={setCategory}/>
    <div className="form-grid"><TextField label="Payment method" value={payment} onChange={setPayment} placeholder="Optional"/><TextField label="Notes" value={notes} onChange={setNotes} placeholder="Optional"/></div>
    {error && <p className="form-error" role="alert">{error}</p>}<div className="form-actions"><button type="button" className="button secondary" onClick={onCancel}>Cancel</button><button className="button primary" type="submit">{initial ? 'Save changes' : 'Save transaction'}</button></div></form>;
}
function BudgetForm({ initial, currency, selectedMonth, onSave, onCancel }: { initial?: Budget; currency: Currency; selectedMonth: string; onSave: (b: Budget) => boolean; onCancel: () => void }) {
  const [category, setCategory] = useState(initial?.category ?? EXPENSE_CATEGORIES[0]); const [month, setMonth] = useState(initial?.month ?? selectedMonth); const [limit, setLimit] = useState(amountInput(initial?.limitMinor, currency)); const [rollover, setRollover] = useState(initial?.rollover ?? false); const [error, setError] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); try { const limitMinor = toMinor(limit, currency); if (!month) throw new Error('Choose a budget month.'); if (onSave({ id: initial?.id ?? uid(), category, month, limitMinor, rollover })) onCancel(); } catch (e) { setError(e instanceof Error ? e.message : 'Check the form.'); } };
  return <form className="form" onSubmit={submit}><div className="form-grid"><SelectField label="Budget for" value={category} options={['All categories', ...EXPENSE_CATEGORIES]} onChange={setCategory}/><TextField label="Month" type="month" value={month} onChange={setMonth} required/></div><TextField label={`Monthly allowance (${currency})`} type="number" min="0" step={String(1 / (10 ** digitsFor(currency)))} value={limit} onChange={setLimit} required/>
    <label className="check-row"><input type="checkbox" checked={rollover} onChange={e => setRollover(e.target.checked)}/><span><b>Carry unused allowance forward</b><small>Only a positive remainder rolls into the next month. Overspending does not carry over.</small></span></label>
    {error && <p className="form-error" role="alert">{error}</p>}<div className="form-actions"><button type="button" className="button secondary" onClick={onCancel}>Cancel</button><button className="button primary">Save budget</button></div></form>;
}
function GoalForm({ initial, currency, onSave, onCancel }: { initial?: Goal; currency: Currency; onSave: (g: Goal) => void; onCancel: () => void }) {
  const [title, setTitle] = useState(initial?.title ?? ''); const [target, setTarget] = useState(amountInput(initial?.targetMinor, currency)); const [deadline, setDeadline] = useState(initial?.deadline ?? ''); const [icon, setIcon] = useState(initial?.icon ?? '✦'); const [error, setError] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); try { if (!title.trim()) throw new Error('Give this goal a name.'); const targetMinor = toMinor(target, currency); onSave({ id: initial?.id ?? uid(), title: title.trim(), targetMinor, deadline: deadline || undefined, icon, archived: false, contributions: initial?.contributions ?? [] }); onCancel(); } catch (e) { setError(e instanceof Error ? e.message : 'Check the form.'); } };
  return <form className="form" onSubmit={submit}><TextField label="Goal name" value={title} onChange={setTitle} required placeholder="Emergency fund, trip, new laptop…"/><div className="form-grid"><TextField label={`Target (${currency})`} value={target} onChange={setTarget} type="number" min="0" step={String(1 / (10 ** digitsFor(currency)))} required/><TextField label="Target date" value={deadline} onChange={setDeadline} type="date"/></div><SelectField label="Symbol" value={icon} options={['✦', '⌂', '✈', '♡', '▣', '◎', '☼']} onChange={setIcon}/>
    {error && <p className="form-error" role="alert">{error}</p>}<div className="form-actions"><button type="button" className="button secondary" onClick={onCancel}>Cancel</button><button className="button primary">Save goal</button></div></form>;
}
function ReminderForm({ initial, defaultTime, currency, onSave, onCancel }: { initial?: Reminder; defaultTime: string; currency: Currency; onSave: (r: Reminder) => void; onCancel: () => void }) {
  const [title, setTitle] = useState(initial?.title ?? ''); const [date, setDate] = useState(initial?.dueDate ?? today()); const [time, setTime] = useState(initial?.time ?? defaultTime); const [recurrence, setRecurrence] = useState<Reminder['recurrence']>(initial?.recurrence ?? 'none'); const [category, setCategory] = useState(initial?.category ?? 'Bills and Utilities'); const [amount, setAmount] = useState(amountInput(initial?.amountMinor, currency)); const [description, setDescription] = useState(initial?.description ?? ''); const [error, setError] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); try { if (!title.trim()) throw new Error('Add a reminder title.'); if (!date) throw new Error('Choose a due date.'); onSave({ id: initial?.id ?? uid(), title: title.trim(), dueDate: date, time, recurrence, category: category || undefined, amountMinor: amount ? toMinor(amount, currency) : undefined, description: description.trim() || undefined, status: 'upcoming', createdAt: initial?.createdAt ?? new Date().toISOString() }); onCancel(); } catch (e) { setError(e instanceof Error ? e.message : 'Check the form.'); } };
  return <form className="form" onSubmit={submit}><TextField label="Reminder" value={title} onChange={setTitle} required placeholder="Rent, electricity bill, birthday…"/><div className="form-grid"><TextField label="Due date" type="date" value={date} onChange={setDate} required/><TextField label="Time" type="time" value={time} onChange={setTime}/></div><div className="form-grid"><SelectField label="Repeats" value={recurrence} options={['none', 'monthly', 'yearly']} onChange={v => setRecurrence(v as Reminder['recurrence'])}/><SelectField label="Category" value={category} options={['Bills and Utilities', 'Housing and Rent', 'Subscriptions', 'Health', 'Education', 'Travel', 'Personal', 'Other']} onChange={setCategory}/></div><div className="form-grid"><TextField label={`Expected amount (${currency})`} value={amount} onChange={setAmount} type="number" min="0" step={String(1 / (10 ** digitsFor(currency)))} placeholder="Optional"/><TextField label="Details" value={description} onChange={setDescription} placeholder="Optional"/></div>
    {error && <p className="form-error" role="alert">{error}</p>}<div className="form-actions"><button type="button" className="button secondary" onClick={onCancel}>Cancel</button><button className="button primary">Save reminder</button></div></form>;
}
function ChallengeForm({ initial, currency, onSave, onCancel }: { initial?: Challenge; currency: Currency; onSave: (c: Challenge) => void; onCancel: () => void }) {
  const [title, setTitle] = useState(initial?.title ?? ''); const [description, setDescription] = useState(initial?.description ?? ''); const [start, setStart] = useState(initial?.startDate ?? today()); const [end, setEnd] = useState(initial?.endDate ?? today()); const [categories, setCategories] = useState(initial?.categories.join(', ') ?? EXPENSE_CATEGORIES[0]); const [keywords, setKeywords] = useState(initial?.keywords.join(', ') ?? ''); const [cap, setCap] = useState(amountInput(initial?.capMinor, currency)); const [error, setError] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); if (!title.trim() || !start || !end || end < start) { setError('Add a title and a valid date range.'); return; } try { const capMinor = cap ? toMinor(cap, currency) : undefined; onSave({ id: initial?.id ?? uid(), title: title.trim(), description: description.trim() || undefined, startDate: start, endDate: end, categories: categories.split(',').map(v => v.trim()).filter(Boolean), keywords: keywords.split(',').map(v => v.trim().toLowerCase()).filter(Boolean), capMinor }); onCancel(); } catch (e) { setError(e instanceof Error ? e.message : 'Check the spending cap.'); } };
  return <form className="form" onSubmit={submit}><TextField label="Challenge" value={title} onChange={setTitle} required placeholder="No food delivery for a week"/><TextField label="What are you aiming for?" value={description} onChange={setDescription} placeholder="Optional, keep it kind and practical"/><div className="form-grid"><TextField label="Starts" type="date" value={start} onChange={setStart} required/><TextField label="Ends" type="date" value={end} onChange={setEnd} required/></div><TextField label="Expense categories (comma separated)" value={categories} onChange={setCategories} placeholder="Food and Dining"/><TextField label="Description keywords (optional)" value={keywords} onChange={setKeywords} placeholder="delivery, cafe"/><TextField label="Optional spending cap (amount)" type="number" min="0" value={cap} onChange={setCap} placeholder="No cap"/>
    {error && <p className="form-error" role="alert">{error}</p>}<div className="form-actions"><button type="button" className="button secondary" onClick={onCancel}>Cancel</button><button className="button primary">Save challenge</button></div></form>;
}
function ContributionForm({ initial, currency, onSave, onCancel }: { initial?: Goal['contributions'][number]; currency: Currency; onSave: (c: Goal['contributions'][number]) => boolean; onCancel: () => void }) {
  const [type, setType] = useState<'deposit' | 'withdrawal'>(initial?.type ?? 'deposit'); const [amount, setAmount] = useState(amountInput(initial?.amountMinor, currency)); const [note, setNote] = useState(initial?.note ?? ''); const [error, setError] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); try { const amountMinor = toMinor(amount, currency); const ok = onSave({ id: initial?.id ?? uid(), date: initial?.date ?? today(), type, amountMinor, note: note.trim() || undefined }); if (ok) onCancel(); } catch (e) { setError(e instanceof Error ? e.message : 'Check the amount.'); } };
  return <form className="form" onSubmit={submit}><div className="segmented"><button type="button" className={type === 'deposit' ? 'selected income-choice' : ''} onClick={() => setType('deposit')}>Add to goal</button><button type="button" className={type === 'withdrawal' ? 'selected expense-choice' : ''} onClick={() => setType('withdrawal')}>Withdraw</button></div><p className="muted">This is an allocation of money you already recorded. It does not count as income or an ordinary expense.</p><TextField label={`Amount (${currency})`} value={amount} onChange={setAmount} type="number" min="0" step={String(1 / (10 ** digitsFor(currency)))} required/><TextField label="Note" value={note} onChange={setNote} placeholder="Optional"/>{error && <p className="form-error" role="alert">{error}</p>}<div className="form-actions"><button type="button" className="button secondary" onClick={onCancel}>Cancel</button><button className="button primary">Save movement</button></div></form>;
}

export default function App() {
  const [state, setState] = useState<LedgerState>(DEFAULT_STATE); const [locked, setLocked] = useState(false); const [storageError, setStorageError] = useState(false); const [ready, setReady] = useState(false);
  const [localNow, setLocalNow] = useState(() => new Date());
  const [page, setPage] = useState<Page>('Overview'); const [month, setMonth] = useState(monthKey(new Date())); const [modal, setModal] = useState<Modal>(null); const [toast, setToast] = useState(''); const [online, setOnline] = useState(navigator.onLine); const [updateReady, setUpdateReady] = useState(false); const [mobileNavOpen, setMobileNavOpen] = useState(false); const [installPrompt, setInstallPrompt] = useState<Event | null>(null); const [pendingImport, setPendingImport] = useState<BackupPackage | null>(null); const [search, setSearch] = useState(''); const [typeFilter, setTypeFilter] = useState('all'); const [categoryFilter, setCategoryFilter] = useState('all'); const [fromDate, setFromDate] = useState(''); const [toDate, setToDate] = useState(''); const [transactionLimit, setTransactionLimit] = useState(50); const [sortBy, setSortBy] = useState('date-desc'); const [reminderDraft, setReminderDraft] = useState<Partial<Reminder> | undefined>(); const [unlockPin, setUnlockPin] = useState(''); const [unlockError, setUnlockError] = useState(''); const [lockForm, setLockForm] = useState({ pin: '', confirm: '', backupDone: false });
  const currency = state.profile.currency;
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 3200); };

  useEffect(() => {
    const status = inspectStorage(); setStorageError(!!status.error);
    if (status.locked) setLocked(true); else if (!status.error) setState(loadPlain());
    setReady(true);
  }, []);
  useEffect(() => { if (!ready || locked || storageError) return; const id = window.setTimeout(() => { saveState(state).catch(() => notify('Could not save this change. Check available browser storage.')); }, 180); return () => window.clearTimeout(id); }, [state, locked, ready, storageError]);
  useEffect(() => { const on = () => setOnline(true); const off = () => setOnline(false); window.addEventListener('online', on); window.addEventListener('offline', off); return () => { window.removeEventListener('online', on); window.removeEventListener('offline', off); }; }, []);
  useEffect(() => { const timer = window.setInterval(() => setLocalNow(new Date()), 60_000); return () => window.clearInterval(timer); }, []);
  useEffect(() => {
    if (!mobileNavOpen) return;
    const previousFocus = document.activeElement as HTMLElement | null; document.body.style.overflow = 'hidden';
    const menu = document.querySelector<HTMLElement>('.mobile-menu-sheet'); const focusable = () => [...(menu?.querySelectorAll<HTMLElement>('button,[tabindex]:not([tabindex="-1"])') ?? [])];
    focusable()[0]?.focus();
    const key = (e: KeyboardEvent) => { if (e.key === 'Escape') setMobileNavOpen(false); if (e.key === 'Tab') { const items = focusable(); if (e.shiftKey && document.activeElement === items[0]) { e.preventDefault(); items.at(-1)?.focus(); } else if (!e.shiftKey && document.activeElement === items.at(-1)) { e.preventDefault(); items[0]?.focus(); } } };
    window.addEventListener('keydown', key); return () => { window.removeEventListener('keydown', key); document.body.style.overflow = ''; if (previousFocus?.isConnected) previousFocus.focus(); };
  }, [mobileNavOpen]);
  useEffect(() => { const fn = (e: Event) => { e.preventDefault(); setInstallPrompt(e); }; window.addEventListener('beforeinstallprompt', fn); return () => window.removeEventListener('beforeinstallprompt', fn); }, []);
  useEffect(() => {
    if (!('serviceWorker' in navigator)) return;
    navigator.serviceWorker.register('./sw.js').then(reg => { if (reg.waiting) setUpdateReady(true); reg.addEventListener('updatefound', () => { const installing = reg.installing; installing?.addEventListener('statechange', () => { if (installing.state === 'installed' && navigator.serviceWorker.controller) setUpdateReady(true); }); }); }).catch(() => {});
  }, []);
  useEffect(() => {
    if (!ready || locked || !state.profile.lockEnabled || storageError) return;
    let timer: number; const minutes = Math.max(1, state.profile.autoLockMinutes || 10);
    const reset = () => { window.clearTimeout(timer); timer = window.setTimeout(async () => { try { await saveState(state); } catch {} lockMemory(); setState(DEFAULT_STATE); setLocked(true); notify('Ledgerly locked after inactivity.'); }, minutes * 60_000); };
    const events: (keyof WindowEventMap)[] = ['pointerdown', 'keydown', 'touchstart', 'mousemove']; events.forEach(e => window.addEventListener(e, reset, { passive: true })); reset();
    return () => { window.clearTimeout(timer); events.forEach(e => window.removeEventListener(e, reset)); };
  }, [ready, locked, state.profile.lockEnabled, state.profile.autoLockMinutes, storageError]);
  useEffect(() => {
    if (!state.profile.notificationsEnabled || !('Notification' in window) || Notification.permission !== 'granted') return;
    const check = () => { const now = new Date(); state.reminders.filter(r => r.status === 'upcoming' && (r.snoozedUntil ?? r.dueDate) === today()).forEach(r => { const due = new Date(`${r.snoozedUntil ?? r.dueDate}T${r.time || '09:00'}:00`); const occurrence = `${r.id}:${r.snoozedUntil ?? r.dueDate}:${r.time}`; let stored = false; try { stored = sessionStorage.getItem(`ledgerly.notified.${occurrence}`) === '1'; } catch {} if (due <= now && !notifiedReminderOccurrences.has(occurrence) && !stored) { notifiedReminderOccurrences.add(occurrence); try { sessionStorage.setItem(`ledgerly.notified.${occurrence}`, '1'); } catch {} new Notification(`Ledgerly reminder: ${r.title}`, { body: 'Open Ledgerly to review or snooze this reminder.', icon: './ledgerly-icon.svg' }); } }); };
    check(); const timer = window.setInterval(check, 60_000); document.addEventListener('visibilitychange', check); return () => { clearInterval(timer); document.removeEventListener('visibilitychange', check); };
  }, [state.profile.notificationsEnabled, state.reminders]);

  const monthTotals = useMemo(() => totals(state.transactions, month), [state.transactions, month]);
  const available = useMemo(() => lifetimeBalance(state.transactions) - state.goals.reduce((sum, g) => sum + goalBalance(g), 0), [state.transactions, state.goals]);
  const allTransactions = useMemo(() => safeTransactions(state.transactions), [state.transactions]);
  const visibleTransactions = useMemo(() => allTransactions.filter(t => (!search || `${t.description} ${t.category} ${t.notes ?? ''}`.toLowerCase().includes(search.toLowerCase())) && (typeFilter === 'all' || t.type === typeFilter) && (categoryFilter === 'all' || t.category === categoryFilter) && (!fromDate || t.date >= fromDate) && (!toDate || t.date <= toDate)).sort((a, b) => sortBy === 'amount-desc' ? b.amountMinor - a.amountMinor : sortBy === 'amount-asc' ? a.amountMinor - b.amountMinor : sortBy === 'date-asc' ? a.date.localeCompare(b.date) : b.date.localeCompare(a.date)), [allTransactions, search, typeFilter, categoryFilter, fromDate, toDate, sortBy]);
  const selectedBudgets = state.budgets.filter(b => b.month === month);
  const monthExpenses = allTransactions.filter(t => t.type === 'expense' && monthKey(t.date) === month);
  const categoryTotals = Object.entries(monthExpenses.reduce<Record<string, number>>((acc, t) => { acc[t.category || 'Uncategorized'] = (acc[t.category || 'Uncategorized'] ?? 0) + t.amountMinor; return acc; }, {})).sort((a, b) => b[1] - a[1]);
  const activeGoals = state.goals.filter(g => !g.archived);
  const activeReminders = state.reminders.filter(r => r.status === 'upcoming').sort((a, b) => `${a.snoozedUntil ?? a.dueDate}${a.time}`.localeCompare(`${b.snoozedUntil ?? b.dueDate}${b.time}`));
  const hourGreeting = greetingFor(state.profile.name, localNow.getHours());

  const saveTransaction = (t: Transaction) => { setState(s => ({ ...s, transactions: [t, ...s.transactions.filter(old => old.id !== t.id)] })); notify('Transaction saved. Your totals are up to date.'); return true; };
  const deleteTransaction = (id: string) => { if (!window.confirm('Delete this transaction? Your totals, reports and budgets will recalculate.')) return; setState(s => ({ ...s, transactions: s.transactions.filter(t => t.id !== id) })); notify('Transaction deleted.'); };
  const saveBudget = (b: Budget) => { if (state.budgets.some(old => old.id !== b.id && old.month === b.month && old.category === b.category)) { notify('A budget already exists for that category and month. Edit it instead.'); return false; } setState(s => ({ ...s, budgets: [b, ...s.budgets.filter(old => old.id !== b.id)] })); notify('Budget saved.'); return true; };
  const deleteBudget = (id: string) => { if (!window.confirm('Delete this budget?')) return; setState(s => ({ ...s, budgets: s.budgets.filter(b => b.id !== id) })); notify('Budget deleted.'); };
  const saveGoal = (g: Goal) => { setState(s => ({ ...s, goals: [g, ...s.goals.filter(old => old.id !== g.id)] })); notify('Savings goal saved.'); };
  const deleteGoal = (id: string) => { if (!window.confirm('Delete this goal and its contribution history? This cannot be undone.')) return; setState(s => ({ ...s, goals: s.goals.filter(g => g.id !== id) })); notify('Goal deleted.'); };
  const saveReminder = (r: Reminder) => { setState(s => ({ ...s, reminders: [r, ...s.reminders.filter(old => old.id !== r.id)] })); setReminderDraft(undefined); notify('Reminder saved.'); };
  const deleteReminder = (id: string) => { if (!window.confirm('Delete this reminder?')) return; setState(s => ({ ...s, reminders: s.reminders.filter(r => r.id !== id) })); notify('Reminder deleted.'); };
  const completeReminder = (reminder: Reminder) => {
    const done = { ...reminder, status: 'done' as const, snoozedUntil: undefined };
    let next: Reminder | null = null;
    if (reminder.recurrence !== 'none') {
      const old = dateOf(reminder.dueDate); const desiredDay = old.getDate(); let year = old.getFullYear(); let monthIndex = old.getMonth();
      const nextOccurrence = () => { if (reminder.recurrence === 'monthly') monthIndex += 1; else year += 1; const lastDay = new Date(year, monthIndex + 1, 0).getDate(); return new Date(year, monthIndex, Math.min(desiredDay, lastDay), 12); };
      let due = nextOccurrence(); while (`${due.getFullYear()}-${String(due.getMonth() + 1).padStart(2, '0')}-${String(due.getDate()).padStart(2, '0')}` <= today()) due = nextOccurrence();
      next = { ...reminder, id: uid(), dueDate: `${due.getFullYear()}-${String(due.getMonth() + 1).padStart(2, '0')}-${String(due.getDate()).padStart(2, '0')}`, snoozedUntil: undefined, status: 'upcoming', createdAt: new Date().toISOString() };
    }
    setState(s => ({ ...s, reminders: [ ...(next ? [next] : []), done, ...s.reminders.filter(r => r.id !== reminder.id) ] }));
    if (reminder.amountMinor && window.confirm('Create an expense transaction for this payment?')) {
      const transaction: Transaction = { id: uid(), description: reminder.title, type: 'expense', amountMinor: reminder.amountMinor, category: reminder.category || 'Bills and Utilities', date: today(), createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() };
      setState(s => ({ ...s, transactions: [transaction, ...s.transactions] })); notify('Reminder completed and expense recorded.');
    } else notify('Reminder completed.');
  };
  const snoozeReminder = (r: Reminder) => { const due = new Date(); due.setDate(due.getDate() + 1); const d = `${due.getFullYear()}-${String(due.getMonth() + 1).padStart(2, '0')}-${String(due.getDate()).padStart(2, '0')}`; setState(s => ({ ...s, reminders: s.reminders.map(item => item.id === r.id ? { ...item, snoozedUntil: d } : item) })); notify('Snoozed until tomorrow.'); };
  const saveContribution = (goalId: string, contribution: Goal['contributions'][number]) => {
    const goal = state.goals.find(g => g.id === goalId); if (!goal) return false;
    const previous = goal.contributions.find(c => c.id === contribution.id);
    const priorSigned = previous ? (previous.type === 'deposit' ? previous.amountMinor : -previous.amountMinor) : 0;
    const totalSavedWithoutEdit = state.goals.reduce((sum, g) => sum + goalBalance(g), 0) - priorSigned;
    const goalBalanceWithoutEdit = goalBalance(goal) - priorSigned;
    if (contribution.type === 'deposit' && contribution.amountMinor > lifetimeBalance(state.transactions) - totalSavedWithoutEdit) { notify('This contribution is larger than your available recorded funds.'); return false; }
    if (contribution.type === 'withdrawal' && contribution.amountMinor > goalBalanceWithoutEdit) { notify('A withdrawal cannot exceed this goal’s saved amount.'); return false; }
    setState(s => ({ ...s, goals: s.goals.map(g => g.id === goalId ? { ...g, contributions: [...g.contributions.filter(c => c.id !== contribution.id), contribution] } : g) })); notify(previous ? 'Contribution updated.' : contribution.type === 'deposit' ? 'Contribution added.' : 'Withdrawal recorded.'); return true;
  };
  const removeContribution = (goalId: string, contributionId: string) => { if (!window.confirm('Delete this contribution history entry? The goal balance and available balance will recalculate.')) return; setState(s => ({ ...s, goals: s.goals.map(g => g.id === goalId ? { ...g, contributions: g.contributions.filter(c => c.id !== contributionId) } : g) })); notify('Contribution entry deleted.'); };
  const archiveGoal = (goalId: string, archived: boolean) => { setState(s => ({ ...s, goals: s.goals.map(g => g.id === goalId ? { ...g, archived } : g) })); notify(archived ? 'Goal archived.' : 'Goal restored.'); };

  const getChallenge = (challenge: Challenge) => {
    const matches = allTransactions.filter(t => t.type === 'expense' && t.date >= challenge.startDate && t.date <= challenge.endDate && (challenge.categories.length === 0 || challenge.categories.includes(t.category)) && (challenge.keywords.length === 0 || challenge.keywords.some(k => t.description.toLowerCase().includes(k) || (t.notes ?? '').toLowerCase().includes(k))));
    const spentMinor = matches.reduce((sum, t) => sum + t.amountMinor, 0); const now = today(); const totalDays = Math.max(1, Math.floor((dateOf(challenge.endDate).getTime() - dateOf(challenge.startDate).getTime()) / 86_400_000) + 1); const elapsed = Math.max(0, Math.min(totalDays, Math.floor((dateOf(now).getTime() - dateOf(challenge.startDate).getTime()) / 86_400_000) + 1));
    const status = now < challenge.startDate ? 'Upcoming' : now > challenge.endDate ? 'Complete' : challenge.capMinor && spentMinor > challenge.capMinor ? 'Over cap' : !challenge.capMinor && spentMinor > 0 ? 'Spending recorded' : 'In progress'; const progress = challenge.capMinor ? Math.min(100, spentMinor / challenge.capMinor * 100) : elapsed / totalDays * 100;
    return { matches, spentMinor, status, progress, elapsed, totalDays, remaining: Math.max(0, Math.ceil((dateOf(challenge.endDate).getTime() - dateOf(now).getTime()) / 86_400_000)) };
  };
  const changeChallenge = (c: Challenge) => { setState(s => ({ ...s, challenges: [c, ...s.challenges.filter(old => old.id !== c.id)] })); notify('Challenge saved. Progress uses only transactions you record.'); };
  const deleteChallenge = (id: string) => { if (!window.confirm('Delete this challenge?')) return; setState(s => ({ ...s, challenges: s.challenges.filter(c => c.id !== id) })); notify('Challenge deleted.'); };

  const handleNaturalLanguage = (text: string) => { setReminderDraft(parseReminderText(text, state.profile.reminderTime, currency)); setModal({ kind: 'reminder' }); };

  const openExport = () => downloadFile(`ledgerly-backup-${today()}.json`, JSON.stringify(makePackage(state), null, 2));
  const onImportFile = async (file?: File) => {
    if (!file) return;
    try { const candidate = JSON.parse(await file.text()); let pack: BackupPackage;
      if (candidate?.app === 'Ledgerly encrypted transfer') { const passphrase = window.prompt('Enter the transfer passphrase.'); if (!passphrase) return; pack = await decryptPackage(candidate, passphrase); }
      else pack = validatePackage(candidate);
      setPendingImport(pack); setModal({ kind: 'import' });
    } catch (e) { notify(e instanceof Error ? e.message : 'Could not read this backup. Existing data is unchanged.'); }
  };
  const restoreLockedFile = async (file?: File) => {
    if (!file) return;
    try {
      const candidate = JSON.parse(await file.text());
      const phrase = candidate?.app === 'Ledgerly encrypted transfer' ? window.prompt('Enter the transfer passphrase.') : null;
      if (candidate?.app === 'Ledgerly encrypted transfer' && !phrase) return;
      const backup = candidate?.app === 'Ledgerly encrypted transfer' ? await decryptPackage(candidate, phrase!) : validatePackage(candidate);
      if (!window.confirm('Replace the currently locked or unreadable browser copy with this validated backup?')) return;
      disableEncryption(backup.state); setState(backup.state); setLocked(false); setStorageError(false); setPendingImport(null); notify('Backup restored. The browser copy is now unlocked.');
    } catch (e) { notify(e instanceof Error ? e.message : 'Could not restore this backup. Existing browser data is unchanged.'); }
  };
  const importPackage = (mode: 'merge' | 'replace') => {
    if (!pendingImport) return;
    if (mode === 'replace' && !window.confirm('Replace all current Ledgerly records with this backup? This cannot be undone. Export a backup first if you may need the current data.')) return;
    const next = mode === 'merge' ? mergeState(state, pendingImport.state) : pendingImport.state;
    setState({ ...next, profile: { ...next.profile, lockEnabled: state.profile.lockEnabled } }); setModal(null); setPendingImport(null); notify(mode === 'merge' ? 'Backup merged. Existing IDs kept their current values.' : 'Ledgerly data replaced from backup.');
  };
  const exportTransfer = async () => { const phrase = window.prompt('Set a transfer passphrase (at least 8 characters). Share it separately with your other device.'); if (!phrase) return; try { const pack = await encryptPackage(makePackage(state), phrase); const filename = `ledgerly-transfer-${today()}.ledgerly.json`; const contents = JSON.stringify(pack, null, 2); const file = new File([contents], filename, { type: 'application/json' }); if (navigator.share && navigator.canShare?.({ files: [file] })) { await navigator.share({ files: [file], title: 'Ledgerly encrypted transfer', text: 'Encrypted Ledgerly data snapshot. Enter the passphrase separately on the other device.' }); notify('Encrypted transfer shared. The passphrase is not saved.'); } else { downloadFile(filename, contents); notify('Encrypted transfer package downloaded. The passphrase is not saved.'); } } catch (e) { notify(e instanceof Error ? e.message : 'Could not create transfer.'); } };
  const updateProfile = (patch: Partial<LedgerState['profile']>) => setState(s => ({ ...s, profile: { ...s.profile, ...patch } }));
  const lockNow = async () => { try { await saveState(state); } catch {} lockMemory(); setState(DEFAULT_STATE); setLocked(true); setUnlockPin(''); notify('Ledgerly is locked.'); };
  const unlockNow = async (e: FormEvent) => { e.preventDefault(); try { const data = await unlock(unlockPin); setState(data); setLocked(false); setUnlockError(''); setUnlockPin(''); notify('Welcome back.'); } catch { setUnlockError('That PIN did not unlock this data. Try again, or restore a backup.'); } };
  const enableLock = async () => { if (!lockForm.backupDone) { notify('Create a backup before enabling the privacy lock.'); return; } if (!/^\d{6,12}$/.test(lockForm.pin)) { notify('Use a numeric PIN between 6 and 12 digits.'); return; } if (lockForm.pin !== lockForm.confirm) { notify('The PIN entries do not match.'); return; } const next = { ...state, profile: { ...state.profile, lockEnabled: true } }; try { await enableEncryption(lockForm.pin, next); setState(next); setLockForm({ pin: '', confirm: '', backupDone: false }); notify('Privacy lock enabled. Your browser copy is encrypted while locked.'); } catch { notify('Could not enable encryption. Existing data was kept.'); } };
  const replacePin = async () => { if (!/^\d{6,12}$/.test(lockForm.pin) || lockForm.pin !== lockForm.confirm) { notify('Enter the same new 6–12 digit PIN twice.'); return; } try { await changePin(lockForm.pin, state); setLockForm({ pin: '', confirm: '', backupDone: false }); notify('PIN changed.'); } catch { notify('Could not change the PIN. Existing encrypted data was kept.'); } };
  const turnOffLock = () => { if (!window.confirm('Turn off encryption at rest? Ledgerly will store readable financial data in this browser profile.')) return; try { disableEncryption({ ...state, profile: { ...state.profile, lockEnabled: false } }); setState(s => ({ ...s, profile: { ...s.profile, lockEnabled: false } })); notify('Privacy lock disabled.'); } catch { notify('Could not disable the lock.'); } };

  const selectedMonthBudgets = selectedBudgets.map(b => ({ budget: b, calc: budgetAllowance(b, state.budgets, state.transactions) }));
  const monthlyInsight = (() => {
    const prev = changeMonth(month, -1); const previous = state.transactions.filter(t => t.type === 'expense' && monthKey(t.date) === prev); const currentDays = month === monthKey(new Date()) ? new Date().getDate() : monthRange(month).days;
    if (!monthExpenses.length || !previous.length) return null;
    const days = Math.max(1, currentDays); const previousDaily = previous.reduce((a, t) => a + t.amountMinor, 0) / monthRange(prev).days; const currentDaily = monthExpenses.reduce((a, t) => a + t.amountMinor, 0) / days;
    const delta = previousDaily ? (currentDaily - previousDaily) / previousDaily * 100 : 0;
    if (delta > 15) return `Recorded daily spending is ${Math.round(delta)}% higher than ${monthLabel(prev)}’s daily average. This compares spend per calendar day.`;
    if (delta < -15) return `Recorded daily spending is ${Math.round(Math.abs(delta))}% lower than ${monthLabel(prev)}’s daily average. This compares spend per calendar day.`;
    return 'Your recorded daily spending is close to last month’s average.';
  })();

  if (!ready) return <div className="splash"><div className="brand-mark">L</div><p>Loading Ledgerly…</p></div>;
  if (storageError) return <div className="lock-screen"><div className="lock-card"><div className="brand-lock"><span className="brand-mark">L</span><div><b>LEDGERLY</b><small>Personal finance, with clarity.</small></div></div><CircleAlert className="lock-icon"/><h1>Local data needs attention</h1><p>Ledgerly could not read its saved browser data. Your existing storage has not been overwritten. Restore a valid JSON backup, or deliberately reset this browser copy.</p><label className="file-button button secondary"><FileUp size={16}/> Restore backup<input type="file" accept=".json,application/json" onChange={e => restoreLockedFile(e.target.files?.[0])}/></label><button className="button danger" onClick={() => { if (window.confirm('Remove unreadable Ledgerly browser data? This cannot be undone.')) { clearAll(); setStorageError(false); setState(DEFAULT_STATE); notify('Local data removed.'); } }}>Reset unreadable data</button></div>{toast && <div className="toast">{toast}</div>}</div>;
  if (locked) return <div className="lock-screen"><div className="lock-card"><div className="brand-lock"><span className="brand-mark">L</span><div><b>LEDGERLY</b><small>Personal finance, with clarity.</small></div></div><div className="lock-icon-wrap"><LockKeyhole size={25}/></div><p className="eyebrow">PRIVATE FINANCIAL DATA</p><h1>Welcome back</h1><p>Enter your Ledgerly PIN to unlock this browser’s encrypted copy.</p><form className="form" onSubmit={unlockNow}><TextField label="Numeric PIN" value={unlockPin} onChange={setUnlockPin} type="password" required placeholder="••••••"/><button className="button primary full">Unlock Ledgerly</button></form>{unlockError && <p className="form-error" role="alert">{unlockError}</p>}<p className="privacy-note">Forgotten PINs cannot be reset here. Restore a backup if you have one. <label className="file-link">Restore backup<input type="file" accept=".json,application/json" onChange={e => restoreLockedFile(e.target.files?.[0])}/></label></p></div>{toast && <div className="toast">{toast}</div>}</div>;

  return <div className="app-shell">
    <aside className="sidebar"><a className="brand" href="#overview" onClick={e => { e.preventDefault(); setPage('Overview'); }}><span className="brand-mark">L</span><span className="brand-type"><b>LEDGERLY</b><small>Personal finance, with clarity.</small></span></a><div className="side-label">WORKSPACE</div><nav aria-label="Main navigation">{NAV.map(({ name, icon: Icon }) => <button key={name} className={`nav-link ${page === name ? 'active' : ''}`} onClick={() => setPage(name)}><Icon size={18}/><span>{name}</span>{name === 'Reminders' && activeReminders.filter(r => r.dueDate < today()).length > 0 && <i className="nav-dot"/>}</button>)}</nav><div className="sidebar-bottom"><div className="privacy-card"><ShieldCheck size={17}/><span><b>Private by design</b><small>Your records stay in this browser</small></span></div><button className="profile-chip" onClick={() => setPage('Settings')}><span className="avatar">{state.profile.name.trim() ? state.profile.name.trim()[0].toUpperCase() : 'L'}</span><span><b>{state.profile.name || 'Your Ledgerly'}</b><small>{currency} · Local profile</small></span><Settings size={16}/></button></div></aside>
    <main className="main"><header className="topbar"><button className="mobile-brand" onClick={() => setPage('Overview')}><span className="brand-mark">L</span><b>LEDGERLY</b></button><div className="topbar-title"><span className="breadcrumb">Money workspace</span><span className="topbar-page">{page}</span></div><div className="top-actions"><span className={`connection ${online ? '' : 'offline'}`} title={online ? 'Online' : 'Offline'}>{online ? <Wifi size={15}/> : <WifiOff size={15}/>}<span>{online ? 'Local' : 'Offline'}</span></span><button className="button primary top-add" onClick={() => { setModal({ kind: 'transaction' }); setPage('Transactions'); }}><Plus size={17}/> Add transaction</button><button className="icon-button mobile-menu" aria-label="Open navigation" onClick={() => setMobileNavOpen(true)}><Menu size={19}/></button></div></header>
    {!online && <div className="offline-banner"><WifiOff size={15}/> Offline mode · Your saved records and finance tools remain on this device.</div>}
    {updateReady && <div className="update-banner">Ledgerly has an update ready. <button onClick={() => { navigator.serviceWorker.getRegistration().then(r => r?.waiting?.postMessage('SKIP_WAITING')); navigator.serviceWorker.addEventListener('controllerchange', () => location.reload(), { once: true }); }}>Update now</button><button className="banner-dismiss" aria-label="Dismiss update" onClick={() => setUpdateReady(false)}><X size={15}/></button></div>}
    <div className="page-content">
      {page === 'Overview' && <>
        <section className="welcome-row"><div><p className="eyebrow">YOUR MONEY, IN FOCUS</p><h1>{hourGreeting}</h1><p className="muted">A clear view of what’s happening with your money.</p></div><div className="month-switch"><button className="icon-button" aria-label="Previous month" onClick={() => setMonth(m => changeMonth(m, -1))}><ChevronLeft size={18}/></button><span>{monthLabel(month)}</span><button className="icon-button" aria-label="Next month" onClick={() => setMonth(m => changeMonth(m, 1))}><ChevronRight size={18}/></button></div></section>
        <section className="hero-grid"><article className="balance-card"><div className="balance-top"><span>AVAILABLE BALANCE</span><span className="balance-pill"><Wallet size={13}/> Lifetime</span></div><strong>{money(available, currency)}</strong><p>Recorded income less expenses and money allocated to active goals.</p><div className="balance-footer"><span>Selected month · {monthLabel(month)}</span><span>{monthTotals.income - monthTotals.expenses >= 0 ? <ArrowUpRight size={14}/> : <ArrowDownRight size={14}/>} {money(monthTotals.income - monthTotals.expenses, currency)} net</span></div><div className="hero-orb orb-one"/><div className="hero-orb orb-two"/></article><article className="motto-card"><div className="motto-icon"><Sparkles size={17}/></div><span className="eyebrow">A NOTE FOR TODAY</span><blockquote>“{localMotto()}”</blockquote><span className="motto-date">{new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' })}</span></article></section>
        <section className="metric-grid"><Metric label="Income this month" value={money(monthTotals.income, currency)} icon={<TrendingUp size={17}/>} variant="green" sub={`${monthExpenses.length ? 'Based on recorded activity' : 'No income recorded yet'}`}/><Metric label="Expenses this month" value={money(monthTotals.expenses, currency)} icon={<TrendingDown size={17}/>} variant="coral" sub={`${monthExpenses.length} recorded ${monthExpenses.length === 1 ? 'expense' : 'expenses'}`}/><Metric label="Monthly net" value={money(monthTotals.income - monthTotals.expenses, currency)} icon={<ChartPie size={17}/>} variant="amber" sub={monthTotals.income > 0 ? `Savings rate ${((monthTotals.income - monthTotals.expenses) / monthTotals.income * 100).toFixed(1)}%` : 'Savings rate appears after income is recorded'}/></section>
        <section className="content-grid"><article className="panel trend-panel"><PanelHeader title="Cash flow" hint={`Income and expenses · ${monthLabel(month)}`} action={<button className="text-button" onClick={() => setPage('Reports')}>View reports <ArrowUpRight size={14}/></button>}/>{renderTrend(state.transactions, month, currency)}</article><article className="panel category-panel"><PanelHeader title="Spending by category" hint="Selected month"/>{categoryTotals.length ? <div className="category-list">{categoryTotals.slice(0, 5).map(([cat, amount], i) => <CategoryRow key={cat} label={cat} value={amount} max={categoryTotals[0][1]} currency={currency} index={i}/>)}</div> : <Empty text="Category insights appear when you record an expense." action="Add an expense" onClick={() => setModal({ kind: 'transaction' })}/>}</article></section>
        <section className="content-grid lower-grid"><article className="panel"><PanelHeader title="Recent transactions" hint="Latest activity" action={<button className="text-button" onClick={() => setPage('Transactions')}>All transactions <ArrowUpRight size={14}/></button>}/>{allTransactions.length ? <div className="transaction-list">{[...allTransactions].sort((a,b) => b.date.localeCompare(a.date)).slice(0, 5).map(t => <TransactionRow key={t.id} item={t} currency={currency}/>)}</div> : <Empty text="Your money story starts with one entry." action="Add transaction" onClick={() => setModal({ kind: 'transaction' })}/>}</article><article className="panel"><PanelHeader title="Budget pulse" hint={monthLabel(month)} action={<button className="text-button" onClick={() => setPage('Budgets')}>Manage <ArrowUpRight size={14}/></button>}/>{selectedMonthBudgets.length ? <div className="mini-budgets">{selectedMonthBudgets.slice(0, 3).map(({ budget, calc }) => <BudgetProgress key={budget.id} category={budget.category} spent={calc.spentMinor} allowance={calc.allowanceMinor} remaining={calc.remainingMinor} currency={currency}/>)}</div> : <Empty text="Set a monthly budget to keep a gentle eye on spending." action="Create budget" onClick={() => setModal({ kind: 'budget' })}/>}</article></section>
        <section className="content-grid lower-grid"><article className="panel insight-panel"><PanelHeader title="A useful observation" hint="From your recorded activity"/><div className="insight-body"><span className="insight-icon"><Lightbulb size={18}/></span><p>{monthlyInsight ?? (monthExpenses.length ? `Your largest recorded expense category is ${categoryTotals[0]?.[0] ?? 'not available'}. Add more history to compare spending patterns.` : 'No spending pattern to compare yet. Ledgerly will show a useful observation when there is enough recorded history.')}</p></div></article><article className="panel"><PanelHeader title="On the horizon" hint="Upcoming reminders" action={<button className="text-button" onClick={() => setPage('Reminders')}>See all <ArrowUpRight size={14}/></button>}/>{activeReminders.length ? <div className="compact-reminders">{activeReminders.slice(0, 3).map(r => <div key={r.id} className="compact-reminder"><span className="reminder-date">{dateOf(r.snoozedUntil ?? r.dueDate).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</span><div><b>{r.title}</b><small>{r.time}{r.recurrence !== 'none' ? ` · ${r.recurrence}` : ''}</small></div></div>)}</div> : <Empty text="Nothing scheduled. Add a reminder for a bill or important date." action="Add reminder" onClick={() => setModal({ kind: 'reminder' })}/>}</article></section>
        {activeGoals.length > 0 && <section className="panel goal-strip"><PanelHeader title="Savings in motion" hint="Your active goals" action={<button className="text-button" onClick={() => setPage('Savings Goals')}>All goals <ArrowUpRight size={14}/></button>}/><div className="goal-mini-grid">{activeGoals.slice(0, 3).map(g => <GoalMini key={g.id} goal={g} currency={currency}/>)}</div></section>}
        {state.challenges.length > 0 && <section className="panel challenge-strip"><PanelHeader title="Mindful spending" hint="No-spend challenge" action={<button className="text-button" onClick={() => setPage('No-Spend Challenges')}>View challenges <ArrowUpRight size={14}/></button>}/><div className="challenge-mini">{state.challenges.filter(c => !['Upcoming', 'Complete'].includes(getChallenge(c).status)).slice(0, 2).map(c => { const evaluation = getChallenge(c); return <div className="challenge-mini-item" key={c.id}><span className="challenge-flame"><Flame size={18}/></span><div><b>{c.title}</b><small>{evaluation.remaining} days left · {money(evaluation.spentMinor, currency)} recorded</small></div><Progress value={evaluation.progress}/></div>; })}{!state.challenges.some(c => !['Upcoming', 'Complete'].includes(getChallenge(c).status)) && <p className="muted">No active challenges. Progress only includes purchases you record.</p>}</div></section>}
      </>}

      {page === 'Transactions' && <><PageHeading eyebrow="YOUR RECORD" title="Transactions" subtitle="Every recorded inflow and outflow, in one place." action={<button className="button primary" onClick={() => setModal({ kind: 'transaction' })}><Plus size={16}/> Add transaction</button>}/><div className="panel table-panel"><div className="filter-bar"><label className="search-field"><Search size={16}/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search description, category, notes…" aria-label="Search transactions"/></label><select value={typeFilter} onChange={e => setTypeFilter(e.target.value)} aria-label="Filter type"><option value="all">All types</option><option value="income">Income</option><option value="expense">Expense</option></select><select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)} aria-label="Filter category"><option value="all">All categories</option>{[...new Set(allTransactions.map(t => t.category))].sort().map(c => <option key={c}>{c}</option>)}</select><input aria-label="From date" type="date" value={fromDate} onChange={e => { setFromDate(e.target.value); setTransactionLimit(50); }}/><input aria-label="To date" type="date" value={toDate} onChange={e => { setToDate(e.target.value); setTransactionLimit(50); }}/><select value={sortBy} onChange={e => setSortBy(e.target.value)} aria-label="Sort transactions"><option value="date-desc">Newest first</option><option value="date-asc">Oldest first</option><option value="amount-desc">Amount high to low</option><option value="amount-asc">Amount low to high</option></select></div>{visibleTransactions.length ? <><div className="table-head"><span>DESCRIPTION</span><span>DATE</span><span>CATEGORY</span><span>AMOUNT</span><span>ACTIONS</span></div><div className="transaction-list full-list">{visibleTransactions.slice(0, transactionLimit).map(t => <TransactionRow key={t.id} item={t} currency={currency} actions={<><button className="icon-button small" aria-label={`Edit ${t.description}`} onClick={() => setModal({ kind: 'transaction', value: t })}><Pencil size={15}/></button><button className="icon-button small danger-hover" aria-label={`Delete ${t.description}`} onClick={() => deleteTransaction(t.id)}><Trash2 size={15}/></button></>}/>)}</div><div className="table-footer">Showing {Math.min(transactionLimit, visibleTransactions.length)} of {visibleTransactions.length} filtered · {allTransactions.length} total {visibleTransactions.length > transactionLimit && <button className="text-button" onClick={() => setTransactionLimit(limit => limit + 50)}>Load 50 more</button>} <button className="text-button" onClick={() => downloadCSV(visibleTransactions, currency)}><Download size={14}/> Export this view</button></div></> : <Empty text={allTransactions.length ? 'No transactions match these filters.' : 'No transactions yet. Add your first income or expense.'} action={allTransactions.length ? 'Clear filters' : 'Add transaction'} onClick={() => allTransactions.length ? (setSearch(''), setCategoryFilter('all'), setTypeFilter('all'), setFromDate(''), setToDate(''), setTransactionLimit(50)) : setModal({ kind: 'transaction' })}/>}</div></>}

      {page === 'Budgets' && <><PageHeading eyebrow="SPENDING PLAN" title="Budgets" subtitle="Set a monthly allowance. Ledgerly shows what has been used and what remains." action={<button className="button primary" onClick={() => setModal({ kind: 'budget' })}><Plus size={16}/> New budget</button>}/><div className="period-toolbar"><button className="icon-button" onClick={() => setMonth(m => changeMonth(m, -1))} aria-label="Previous month"><ChevronLeft size={18}/></button><b>{monthLabel(month)}</b><button className="icon-button" onClick={() => setMonth(m => changeMonth(m, 1))} aria-label="Next month"><ChevronRight size={18}/></button><span className="muted">Budget rollovers use the prior month’s positive remainder.</span></div>
        {selectedMonthBudgets.length ? <div className="budget-grid">{selectedMonthBudgets.map(({ budget, calc }) => { const f = forecast(budget, state.budgets, state.transactions); const threshold = calc.percent >= 100 ? 100 : calc.percent >= 90 ? 90 : calc.percent >= 75 ? 75 : 0; return <article className={`panel budget-card ${threshold === 100 ? 'over-budget' : threshold >= 90 ? 'near-budget' : ''}`} key={budget.id}><div className="budget-card-head"><div><span className="category-icon"><Wallet size={17}/></span><h3>{budget.category}</h3><small>{monthLabel(budget.month)} allowance</small></div><div className="row-actions"><button className="icon-button small" aria-label={`Edit ${budget.category} budget`} onClick={() => setModal({ kind: 'budget', value: budget })}><Pencil size={15}/></button><button className="icon-button small danger-hover" aria-label={`Delete ${budget.category} budget`} onClick={() => deleteBudget(budget.id)}><Trash2 size={15}/></button></div></div><div className="budget-amounts"><strong>{money(calc.spentMinor, currency)}</strong><span>of {money(calc.allowanceMinor, currency)}</span></div><Progress value={calc.percent} color={threshold === 100 ? 'coral' : threshold >= 90 ? 'amber' : 'green'}/><div className="budget-stats"><span>{calc.remainingMinor >= 0 ? money(calc.remainingMinor, currency) + ' remaining' : money(Math.abs(calc.remainingMinor), currency) + ' over allowance'}</span><b>{Math.round(calc.percent)}%</b></div>{threshold > 0 && <div className={`threshold-note threshold-${threshold}`}><CircleAlert size={15}/><span>{threshold === 100 ? 'This budget has reached its limit.' : `You have used ${threshold}% or more of this allowance.`}</span></div>}{budget.rollover && <p className="rollover-note">Includes {money(calc.carryMinor, currency)} carried forward from the prior month.</p>}{f ? <div className="forecast-box"><b>Month-end estimate</b><span>{money(f.projectedMinor, currency)} at the current daily pace</span><small>{f.projectedRemainingMinor >= 0 ? `${money(f.projectedRemainingMinor, currency)} projected to remain.` : `${money(Math.abs(f.projectedRemainingMinor), currency)} potential overage.`} Simple current-period estimate.</small></div> : <p className="muted small-text">An estimate needs at least 3 elapsed days and 2 relevant recorded expenses.</p>}</article>; })}</div> : <Empty text="No budgets for this month yet. Give your spending a little structure." action="Create a budget" onClick={() => setModal({ kind: 'budget' })}/>}</>}

      {page === 'Reports' && <><PageHeading eyebrow="PATTERNS, NOT PRESSURE" title="Reports" subtitle="Understand your recorded cash flow and spending patterns." action={<button className="button secondary" onClick={() => downloadCSV(allTransactions, currency)}><Download size={16}/> Export CSV</button>}/><section className="metric-grid report-metrics"><Metric label="Income" value={money(monthTotals.income, currency)} icon={<TrendingUp size={17}/>} variant="green" sub={monthLabel(month)}/><Metric label="Expenses" value={money(monthTotals.expenses, currency)} icon={<TrendingDown size={17}/>} variant="coral" sub={monthLabel(month)}/><Metric label="Net cash flow" value={money(monthTotals.income - monthTotals.expenses, currency)} icon={<ChartPie size={17}/>} variant="amber" sub={monthTotals.income > 0 ? `Savings rate ${((monthTotals.income - monthTotals.expenses) / monthTotals.income * 100).toFixed(1)}%` : 'No income recorded this month'}/></section><section className="content-grid"><article className="panel trend-panel"><PanelHeader title="Six-month cash flow" hint="Recorded income and expenses"/>{renderSixMonthTrend(state.transactions, month, currency)}</article><article className="panel"><PanelHeader title="Category breakdown" hint={monthLabel(month)}/>{categoryTotals.length ? <div className="category-list">{categoryTotals.map(([cat, amount], i) => <CategoryRow key={cat} label={cat} value={amount} max={categoryTotals[0][1]} currency={currency} index={i}/>)}</div> : <Empty text="Record expenses to see category patterns." action="Add expense" onClick={() => setModal({ kind: 'transaction' })}/>}</article></section><section className="content-grid lower-grid"><article className="panel"><PanelHeader title="Daily spending average" hint="Selected month to date"/>{monthExpenses.length ? <div className="report-highlight"><strong>{money(Math.round(monthTotals.expenses / (month === monthKey(new Date()) ? new Date().getDate() : monthRange(month).days)), currency)}</strong><span>per calendar day, based on recorded expenses</span><small>{monthExpenses.length} expenses across the selected month.</small></div> : <Empty text="No recorded expense data for this period."/>}</article><article className="panel insight-panel"><PanelHeader title="Spending observation" hint="A simple period comparison"/><div className="insight-body"><span className="insight-icon"><Lightbulb size={18}/></span><p>{monthlyInsight ?? 'A comparison appears after you have recorded expenses in this and a previous month. Current-month comparisons use per-day averages.'}</p></div>{categoryTotals[0] && <p className="muted small-text">Most recorded spending this month: <b>{categoryTotals[0][0]}</b> · {money(categoryTotals[0][1], currency)}.</p>}</article></section><div className="report-footnote"><CircleAlert size={15}/> Reports compare only records entered in Ledgerly. They are summaries, not professional financial advice.</div></>}

      {page === 'Reminders' && <><PageHeading eyebrow="DATES TO REMEMBER" title="Reminders" subtitle="Keep bills and important dates visible. Browser notifications work best while Ledgerly is open." action={<button className="button primary" onClick={() => { setReminderDraft(undefined); setModal({ kind: 'reminder' }); }}><Plus size={16}/> Add reminder</button>}/><NaturalReminder onParse={handleNaturalLanguage}/><div className="reminder-columns"><section className="panel"><PanelHeader title="Upcoming and overdue" hint="Sorted by due date"/>{activeReminders.length ? <div className="reminder-list">{activeReminders.map(r => { const displayDueDate = r.snoozedUntil ?? r.dueDate; const overdue = displayDueDate < today(); return <article className={`reminder-item ${overdue ? 'is-overdue' : ''}`} key={r.id}><div className="reminder-date-block"><b>{dateOf(r.snoozedUntil ?? r.dueDate).toLocaleDateString(undefined, { day: '2-digit' })}</b><small>{dateOf(r.snoozedUntil ?? r.dueDate).toLocaleDateString(undefined, { month: 'short' })}</small></div><div className="reminder-info"><b>{r.title}</b><span>{r.category ?? 'Personal'} · {r.time}{r.recurrence !== 'none' ? ` · repeats ${r.recurrence}` : ''}</span>{r.description && <small>{r.description}</small>}{r.amountMinor && <strong>{money(r.amountMinor, currency)}</strong>}</div>{overdue && <span className="status-tag overdue-tag">Overdue</span>}<div className="row-actions"><button className="icon-button small" aria-label="Edit reminder" onClick={() => { setReminderDraft(undefined); setModal({ kind: 'reminder', value: r }); }}><Pencil size={15}/></button><button className="icon-button small" aria-label="Snooze until tomorrow" onClick={() => snoozeReminder(r)} title="Snooze 1 day"><Clock3 size={15}/></button><button className="icon-button small" aria-label="Mark reminder done" onClick={() => completeReminder(r)}><Check size={16}/></button><button className="icon-button small danger-hover" aria-label="Delete reminder" onClick={() => deleteReminder(r.id)}><Trash2 size={15}/></button></div></article>; })}</div> : <Empty text="No reminders on the calendar. Add one for rent, a bill, or a date you want to remember." action="Add reminder" onClick={() => setModal({ kind: 'reminder' })}/>}</section><section className="panel notification-panel"><span className="notification-icon"><Bell size={20}/></span><h3>Browser notifications</h3><p className="muted">Best effort only. Browsers may pause notifications when the app is closed, offline, or permission is unavailable. In-app reminders stay here.</p><button className={`button ${state.profile.notificationsEnabled ? 'secondary' : 'primary'}`} onClick={async () => { if (!('Notification' in window)) { notify('This browser does not support notifications.'); return; } if (Notification.permission === 'denied') { notify('Notifications are blocked in browser settings. In-app reminders remain available.'); return; } const permission = Notification.permission === 'granted' ? 'granted' : await Notification.requestPermission(); if (permission === 'granted') { updateProfile({ notificationsEnabled: !state.profile.notificationsEnabled }); notify(state.profile.notificationsEnabled ? 'Browser notifications turned off.' : 'Browser notifications enabled.'); } else notify('Permission was not granted. In-app reminders remain available.'); }}>{state.profile.notificationsEnabled ? 'Turn notifications off' : 'Enable browser notifications'}</button></section></div><section className="panel completed-panel"><PanelHeader title="Completed" hint="Recent completed reminders"/>{state.reminders.filter(r => r.status === 'done').length ? <div className="completed-list">{state.reminders.filter(r => r.status === 'done').slice(0, 8).map(r => <span key={r.id}><CircleCheck size={15}/>{r.title}<small>{monthText(r.dueDate)}</small></span>)}</div> : <p className="muted">Completed reminders will appear here.</p>}</section></>}

      {page === 'Savings Goals' && <><PageHeading eyebrow="SAVE WITH PURPOSE" title="Savings goals" subtitle="Track money allocated to your plans. Contributions are transfers, not new income or expenses." action={<button className="button primary" onClick={() => setModal({ kind: 'goal' })}><Plus size={16}/> New goal</button>}/><div className="goal-balance-note"><PiggyBank size={18}/><span><b>{money(activeGoals.reduce((sum, g) => sum + goalBalance(g), 0), currency)}</b><small>currently allocated across active goals · your available balance reflects this allocation</small></span></div>{activeGoals.length ? <div className="goal-grid">{activeGoals.map(goal => { const saved = goalBalance(goal); const remaining = Math.max(0, goal.targetMinor - saved); const percent = goal.targetMinor > 0 ? Math.min(100, saved / goal.targetMinor * 100) : 0; const deadline = goal.deadline ? dateOf(goal.deadline) : null; const days = deadline ? Math.ceil((deadline.getTime() - dateOf(today()).getTime()) / 86_400_000) : null; const daily = days && days > 0 ? Math.ceil(remaining / days) : null; const monthly = days && days > 0 ? Math.ceil(remaining / Math.max(1, days / 30.4375)) : null; const deposits = goal.contributions.filter(c => c.type === 'deposit'); let estimate = 'Add contributions to build an estimate.'; if (remaining <= 0) estimate = 'Target reached'; else if (deposits.length >= 2) { const first = dateOf([...deposits].sort((a,b) => a.date.localeCompare(b.date))[0].date); const span = Math.max(1, (Date.now() - first.getTime()) / 86_400_000 / 30.4375); const monthlyRate = goalBalance(goal) / span; if (monthlyRate > 0) estimate = `At the observed pace: about ${Math.ceil(remaining / monthlyRate)} months`; } else if (goal.deadline) estimate = days && days > 0 ? `Plan by ${deadline!.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}` : 'Target date has passed'; return <article className="panel goal-card" key={goal.id}><div className="goal-card-head"><span className="goal-symbol">{goal.icon ?? '✦'}</span><div className="goal-title"><h3>{goal.title}</h3><small>{goal.deadline ? `Target · ${deadline!.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })}` : 'No target date'}</small></div><div className="row-actions"><button className="icon-button small" aria-label={`Edit ${goal.title}`} onClick={() => setModal({ kind: 'goal', value: goal })}><Pencil size={15}/></button><button className="text-button archive-goal" aria-label="Archive goal" onClick={() => archiveGoal(goal.id, true)}>Archive</button><button className="icon-button small danger-hover" aria-label="Delete goal" onClick={() => deleteGoal(goal.id)}><Trash2 size={15}/></button></div></div><div className="goal-money"><strong>{money(saved, currency)}</strong><span>of {money(goal.targetMinor, currency)}</span></div><Progress value={percent}/><div className="budget-stats"><span>{remaining > 0 ? `${money(remaining, currency)} to go` : 'Goal complete'}</span><b>{Math.round(percent)}%</b></div><div className="goal-plan"><span>Daily plan<strong>{daily !== null ? money(daily, currency) : '—'}</strong></span><span>Monthly plan<strong>{monthly !== null ? money(monthly, currency) : '—'}</strong></span></div><p className="goal-estimate"><Clock3 size={14}/>{estimate}</p><button className="button primary full" onClick={() => setModal({ kind: 'contribution', goal })}><Plus size={15}/> Add or withdraw funds</button>{goal.contributions.length > 0 && <details className="contribution-history"><summary>Contribution history ({goal.contributions.length})</summary>{[...goal.contributions].sort((a,b) => b.date.localeCompare(a.date)).map(c => <div key={c.id}><span>{c.date} · {c.note || (c.type === 'deposit' ? 'Contribution' : 'Withdrawal')}</span><b className={c.type === 'deposit' ? 'income-text' : 'expense-text'}>{c.type === 'deposit' ? '+' : '−'}{money(c.amountMinor, currency)}</b><div className="row-actions contribution-actions"><button className="icon-button small" aria-label="Edit contribution" onClick={() => setModal({ kind: 'contribution', goal, contribution: c })}><Pencil size={13}/></button><button className="icon-button small danger-hover" aria-label="Delete contribution" onClick={() => removeContribution(goal.id, c.id)}><Trash2 size={13}/></button></div></div>)}</details>}</article>; })}</div> : <div className="panel"><Empty text="Your goals start with a target and one contribution. No sample savings have been added." action="Create a savings goal" onClick={() => setModal({ kind: 'goal' })}/></div>}{state.goals.some(g => g.archived) && <section className="panel archived-goals"><details><summary>Archived goals ({state.goals.filter(g => g.archived).length})</summary>{state.goals.filter(g => g.archived).map(g => <div className="archived-goal-row" key={g.id}><span><b>{g.title}</b><small>{money(goalBalance(g), currency)} saved of {money(g.targetMinor, currency)}</small></span><button className="text-button" onClick={() => archiveGoal(g.id, false)}>Restore</button><button className="icon-button small danger-hover" aria-label="Delete archived goal" onClick={() => deleteGoal(g.id)}><Trash2 size={14}/></button></div>)}</details></section>}</>}

      {page === 'No-Spend Challenges' && <><PageHeading eyebrow="MINDFUL SPENDING" title="No-spend challenges" subtitle="A calm way to try a spending intention. Progress includes only expenses you record." action={<button className="button primary" onClick={() => setModal({ kind: 'challenge' })}><Plus size={16}/> Create challenge</button>}/>{state.challenges.length ? <div className="challenge-grid">{state.challenges.map(c => { const evaluation = getChallenge(c); const capped = !!c.capMinor; return <article className="panel challenge-card" key={c.id}><div className="challenge-head"><span className="challenge-flame"><Flame size={18}/></span><span className={`status-tag ${evaluation.status === 'In progress' || evaluation.status === 'Spending recorded' || evaluation.status === 'Over cap' ? 'active-tag' : ''}`}>{evaluation.status}</span><div className="row-actions"><button className="icon-button small" aria-label="Edit challenge" onClick={() => setModal({ kind: 'challenge', value: c })}><Pencil size={15}/></button><button className="icon-button small danger-hover" aria-label="Delete challenge" onClick={() => deleteChallenge(c.id)}><Trash2 size={15}/></button></div></div><h3>{c.title}</h3><p className="muted">{c.description || 'A personal spending intention, tracked from your records.'}</p><div className="challenge-dates"><span>{monthText(c.startDate)}</span><span>→</span><span>{monthText(c.endDate)}</span></div><Progress value={evaluation.progress} color={capped && evaluation.spentMinor > (c.capMinor ?? 0) ? 'coral' : 'green'}/><div className="budget-stats"><span>{capped ? `${money(evaluation.spentMinor, currency)} of ${money(c.capMinor ?? 0, currency)} spent` : `${evaluation.elapsed} of ${evaluation.totalDays} days`}</span><b>{Math.round(evaluation.progress)}%</b></div><div className="challenge-matches"><b>{evaluation.matches.length} matching recorded {evaluation.matches.length === 1 ? 'expense' : 'expenses'}</b><small>{c.categories.length ? c.categories.join(', ') : 'All categories'}{c.keywords.length ? ` · keywords: ${c.keywords.join(', ')}` : ''}</small>{evaluation.matches.slice(0, 3).map(t => <span key={t.id}>{t.date} · {t.description} <b>{money(t.amountMinor, currency)}</b></span>)}</div><p className="challenge-footnote">This does not detect purchases you have not entered in Ledgerly.</p></article>; })}</div> : <div className="panel"><Empty text="Choose a gentle spending intention, date range, and category to get started." action="Create a challenge" onClick={() => setModal({ kind: 'challenge' })}/></div>}</>}

      {page === 'Settings' && <><PageHeading eyebrow="YOUR PREFERENCES" title="Settings" subtitle="Personalize Ledgerly and manage your local records." action={state.profile.lockEnabled ? <button className="button secondary" onClick={lockNow}><LockKeyhole size={15}/> Lock now</button> : undefined}/><section className="panel install-panel"><span className="setting-icon"><Download size={18}/></span><div><b>Install Ledgerly</b><p>{installPrompt ? "Your browser can install Ledgerly from this button." : "If installation is unavailable here, use your browser menu and choose Install app or Add to Home Screen."}</p></div><button className="button secondary" disabled={!installPrompt} onClick={async () => { const prompt = installPrompt as Event & { prompt?: () => Promise<void> }; await prompt.prompt?.(); setInstallPrompt(null); }}>Install</button></section><div className="settings-grid"><section className="panel settings-panel"><PanelHeader title="Profile and preferences" hint="Saved on this device"/><div className="form settings-form"><TextField label="Display name" value={state.profile.name} onChange={v => updateProfile({ name: v })} placeholder="What should Ledgerly call you?"/><div className="form-grid"><SelectField label="Display currency" value={currency} options={CURRENCIES} onChange={v => updateProfile({ currency: v as Currency })}/><TextField label="Default reminder time" value={state.profile.reminderTime} onChange={v => updateProfile({ reminderTime: v })} type="time"/></div><p className="settings-note"><CircleAlert size={15}/> Currency changes only the display format. Recorded amounts are not converted and should use one consistent currency.</p><TextField label="Auto-lock after inactivity (minutes)" value={state.profile.autoLockMinutes} onChange={v => updateProfile({ autoLockMinutes: Math.max(1, Number(v) || 1) })} type="number" min="1" max="120"/><div className="settings-divider"/><div className="setting-intro"><span className="setting-icon"><ShieldCheck size={18}/></span><div><b>Privacy lock</b><p>Encrypt this browser’s saved Ledgerly state with a PIN. A forgotten PIN cannot be reset here.</p></div></div>{state.profile.lockEnabled ? <><div className="privacy-status"><ShieldCheck size={16}/><span><b>Encryption is enabled</b><small>PBKDF2 key derivation · AES-GCM · fresh IV per save. Browser protection is not absolute security.</small></span></div><div className="form-grid"><TextField label="New numeric PIN" value={lockForm.pin} onChange={v => setLockForm(p => ({ ...p, pin: v }))} type="password" placeholder="6–12 digits"/><TextField label="Confirm new PIN" value={lockForm.confirm} onChange={v => setLockForm(p => ({ ...p, confirm: v }))} type="password" placeholder="Repeat PIN"/></div><div className="form-actions left-actions"><button className="button secondary" onClick={replacePin}><LockKeyhole size={15}/> Change PIN</button><button className="button danger" onClick={turnOffLock}>Turn off lock</button></div></> : <><div className="form-grid"><TextField label="Numeric PIN" value={lockForm.pin} onChange={v => setLockForm(p => ({ ...p, pin: v }))} type="password" placeholder="6–12 digits"/><TextField label="Confirm PIN" value={lockForm.confirm} onChange={v => setLockForm(p => ({ ...p, confirm: v }))} type="password" placeholder="Repeat PIN"/></div><label className="check-row"><input type="checkbox" checked={lockForm.backupDone} onChange={e => setLockForm(p => ({ ...p, backupDone: e.target.checked }))}/><span><b>I created a backup</b><small>Enabling encryption without a backup can make data unrecoverable if you forget the PIN.</small></span></label><div className="form-actions left-actions"><button className="button secondary" onClick={openExport}><Download size={15}/> Download backup first</button><button className="button primary" onClick={enableLock}><LockKeyhole size={15}/> Enable privacy lock</button></div></>}<p className="privacy-note">Use a strong PIN, ideally longer than 6 digits. Data is encrypted while saved, but a compromised device or malicious script could still access it while unlocked. Clearing this site’s browser data may delete Ledgerly records.</p></div></section>
        <section className="panel settings-panel"><PanelHeader title="Backup and transfer" hint="Local files · no cloud sync"/><div className="setting-action"><span className="setting-icon"><Download size={18}/></span><div><b>JSON backup</b><p>Versioned snapshot of transactions, budgets, goals and contributions, reminders, challenges, and non-sensitive settings.</p></div><button className="button secondary" onClick={openExport}>Export JSON</button></div><div className="setting-action"><span className="setting-icon"><Upload size={18}/></span><div><b>Restore or import</b><p>Choose merge (existing IDs win) or replace (explicit confirmation) after Ledgerly validates the file.</p></div><label className="file-button button secondary">Import JSON<input type="file" accept=".json,application/json" onChange={e => { onImportFile(e.target.files?.[0]); e.currentTarget.value = ''; }}/></label></div><div className="setting-action"><span className="setting-icon"><Receipt size={18}/></span><div><b>Transaction CSV</b><p>Quoted CSV columns include ID, date, description, type, amount, category, payment method, and notes.</p></div><button className="button secondary" onClick={() => downloadCSV(allTransactions, currency)}>Export CSV</button></div><div className="setting-action transfer-setting"><span className="setting-icon"><ShieldCheck size={18}/></span><div><b>Transfer Ledgerly</b><p>Encrypted portable snapshot for another device. Set a separate passphrase and share it securely. No automatic syncing.</p></div><button className="button secondary" onClick={exportTransfer}>Create encrypted transfer</button></div><div className="settings-note transfer-note"><CircleAlert size={15}/> Cross-device transfer is a snapshot. Transfer again to move later changes; a share link does not sync local data.</div><div className="settings-divider"/><div className="setting-action"><span className="setting-icon"><Bell size={18}/></span><div><b>Browser notifications</b><p>Notifications can be delayed or unavailable while the app is closed. In-app reminders remain available.</p></div><button className="button secondary" onClick={async () => { if (!('Notification' in window)) { notify('Notifications are not supported by this browser.'); return; } const permission = Notification.permission === 'granted' ? 'granted' : await Notification.requestPermission(); if (permission === 'granted') updateProfile({ notificationsEnabled: !state.profile.notificationsEnabled }); else notify('Permission was not granted.'); }}>{state.profile.notificationsEnabled ? 'Turn off' : 'Enable'}</button></div></section></div><section className="panel reset-panel"><div><p className="eyebrow">LOCAL DATA</p><h3>Reset this Ledgerly copy</h3><p>This removes financial records and preferences from this browser profile. Download a backup first if you may need them later.</p></div><button className="button danger" onClick={() => { if (window.confirm('Reset Ledgerly on this browser and remove all locally saved financial records? This cannot be undone.')) { clearAll(); setState(DEFAULT_STATE); setLocked(false); setStorageError(false); notify('Ledgerly was reset on this browser.'); } }}>Reset local data</button></section><section className="about-note"><ShieldCheck size={17}/><p><b>Your local data</b> is tied to this browser profile and website origin. Clearing site data may remove it. Currency selection formats amounts without converting them. Manual transfer does not synchronize devices.</p></section></>}
    </div><footer className="app-footer"><span>LEDGERLY</span><span>Personal finance, with clarity.</span><span>Local-first · {online ? 'Offline ready after caching' : 'Offline'}</span></footer></main>

    <nav className="bottom-nav" aria-label="Mobile navigation">{NAV.filter(item => ['Overview', 'Transactions', 'Budgets', 'Reminders'].includes(item.name)).map(({ name, icon: Icon }) => <button key={name} className={page === name ? 'active' : ''} onClick={() => setPage(name)}><Icon size={18}/><small>{name === 'Transactions' ? 'Activity' : name === 'Reminders' ? 'Dates' : name}</small></button>)}<button className="bottom-add" onClick={() => setModal({ kind: 'transaction' })}><span><Plus size={21}/></span><small>Add</small></button><button className={['Settings', 'Reports', 'Savings Goals', 'No-Spend Challenges'].includes(page) ? 'active' : ''} onClick={() => setMobileNavOpen(true)}><Menu size={18}/><small>More</small></button></nav>
    {mobileNavOpen && <div className="mobile-menu-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) setMobileNavOpen(false); }}><section className="mobile-menu-sheet" role="dialog" aria-modal="true" aria-label="All Ledgerly sections"><header><div><p className="eyebrow">LEDGERLY</p><b>Go to a section</b></div><button className="icon-button" aria-label="Close navigation" onClick={() => setMobileNavOpen(false)}><X size={18}/></button></header><div className="mobile-menu-grid">{NAV.map(({ name, icon: Icon }) => <button key={name} className={page === name ? 'active' : ''} onClick={() => { setPage(name); setMobileNavOpen(false); }}><Icon size={18}/><span>{name}</span></button>)}</div></section></div>}
    {toast && <div className="toast" role="status"><CircleCheck size={17}/>{toast}</div>}
    {installPrompt && <button className="install-chip" onClick={async () => { const prompt = installPrompt as Event & { prompt?: () => Promise<void>; userChoice?: Promise<{ outcome: string }> }; await prompt.prompt?.(); setInstallPrompt(null); }}>{/* browser install prompt */}<Download size={15}/> Install Ledgerly</button>}
    {modal?.kind === 'transaction' && <ModalShell title={modal.value ? 'Edit transaction' : 'Add transaction'} onClose={() => setModal(null)}><TransactionForm key={modal.value?.id ?? 'new-transaction'} initial={modal.value} currency={currency} onSave={saveTransaction} onCancel={() => setModal(null)}/></ModalShell>}
    {modal?.kind === 'budget' && <ModalShell title={modal.value ? 'Edit budget' : 'Create budget'} onClose={() => setModal(null)}><BudgetForm key={modal.value?.id ?? `new-budget-${month}`} initial={modal.value} currency={currency} selectedMonth={month} onSave={saveBudget} onCancel={() => setModal(null)}/></ModalShell>}
    {modal?.kind === 'goal' && <ModalShell title={modal.value ? 'Edit savings goal' : 'Create a savings goal'} onClose={() => setModal(null)}><GoalForm key={modal.value?.id ?? 'new-goal'} initial={modal.value} currency={currency} onSave={saveGoal} onCancel={() => setModal(null)}/></ModalShell>}
    {modal?.kind === 'reminder' && <ModalShell title={modal.value ? 'Edit reminder' : 'Review reminder draft'} onClose={() => { setModal(null); setReminderDraft(undefined); }}><ReminderForm key={modal.value?.id ?? `${reminderDraft?.title ?? 'new'}-${reminderDraft?.dueDate ?? ''}`} initial={modal.value ?? (reminderDraft ? { id: '', title: reminderDraft.title ?? '', dueDate: reminderDraft.dueDate ?? today(), time: reminderDraft.time ?? state.profile.reminderTime, recurrence: reminderDraft.recurrence ?? 'none', category: reminderDraft.category, amountMinor: reminderDraft.amountMinor, description: reminderDraft.description, status: 'upcoming', createdAt: new Date().toISOString() } : undefined)} defaultTime={state.profile.reminderTime} currency={currency} onSave={saveReminder} onCancel={() => { setModal(null); setReminderDraft(undefined); }}/></ModalShell>}
    {modal?.kind === 'challenge' && <ModalShell title={modal.value ? 'Edit challenge' : 'Start a challenge'} onClose={() => setModal(null)}><ChallengeForm key={modal.value?.id ?? 'new-challenge'} initial={modal.value} currency={currency} onSave={changeChallenge} onCancel={() => setModal(null)}/></ModalShell>}
    {modal?.kind === 'contribution' && <ModalShell title={`Move money · ${modal.goal.title}`} onClose={() => setModal(null)}><ContributionForm key={modal.contribution?.id ?? modal.goal.id} initial={modal.contribution} currency={currency} onSave={contribution => saveContribution(modal.goal.id, contribution)} onCancel={() => setModal(null)}/></ModalShell>}
    {modal?.kind === 'import' && pendingImport && <ModalShell title="Import Ledgerly data" onClose={() => { setModal(null); setPendingImport(null); }}><div className="form"><p>This backup contains <b>{pendingImport.state.transactions.length} transactions</b>, {pendingImport.state.budgets.length} budgets, {pendingImport.state.goals.length} goals, {pendingImport.state.reminders.length} reminders, and {pendingImport.state.challenges.length} challenges.</p><button className="button primary full" onClick={() => importPackage('merge')}>Merge with current data</button><small>Existing records with matching IDs keep their current values. New IDs are added.</small><button className="button danger full" onClick={() => importPackage('replace')}>Replace current data…</button><small>Requires a second confirmation. Download a backup first if needed.</small><button className="button secondary full" onClick={() => { setModal(null); setPendingImport(null); }}>Cancel</button></div></ModalShell>}
    </div>;
}

function Metric({ label, value, icon, variant, sub }: { label: string; value: string; icon: ReactNode; variant: string; sub: string }) { return <article className="metric-card"><span className={`metric-icon ${variant}`}>{icon}</span><div><span className="metric-label">{label}</span><strong>{value}</strong><small>{sub}</small></div></article>; }
function PanelHeader({ title, hint, action }: { title: string; hint?: string; action?: ReactNode }) { return <header className="panel-header"><div><h2>{title}</h2>{hint && <p>{hint}</p>}</div>{action}</header>; }
function PageHeading({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle: string; action?: ReactNode }) { return <section className="page-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="muted">{subtitle}</p></div>{action}</section>; }
function Empty({ text, action, onClick }: { text: string; action?: string; onClick?: () => void }) { return <div className="empty-state"><span className="empty-icon"><Sparkles size={19}/></span><p>{text}</p>{action && onClick && <button className="text-button" onClick={onClick}>{action} <ArrowUpRight size={14}/></button>}</div>; }
function TransactionRow({ item, currency, actions }: { item: Transaction; currency: Currency; actions?: ReactNode }) { return <div className="transaction-row"><span className={`tx-icon ${item.type}`} aria-hidden="true">{item.type === 'income' ? <ArrowDownRight size={16}/> : <ArrowUpRight size={16}/>}</span><div className="tx-description"><b>{item.description}</b><small>{item.category}{item.paymentMethod ? ` · ${item.paymentMethod}` : ''}</small></div><span className="tx-date">{dateOf(item.date).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: item.date.slice(0, 4) !== String(new Date().getFullYear()) ? 'numeric' : undefined })}</span><strong className={item.type === 'income' ? 'income-text' : 'expense-text'}>{item.type === 'income' ? '+' : '−'}{money(item.amountMinor, currency)}</strong>{actions && <div className="row-actions tx-actions">{actions}</div>}</div>; }
function Progress({ value, color = 'green' }: { value: number; color?: string }) { return <div className={`progress ${color}`} role="progressbar" aria-valuenow={Math.round(Math.min(100, Math.max(0, value)))} aria-valuemin={0} aria-valuemax={100}><span style={{ width: `${Math.min(100, Math.max(0, value))}%` }}/></div>; }
function CategoryRow({ label, value, max, currency, index }: { label: string; value: number; max: number; currency: Currency; index: number }) { return <div className="category-row"><div className="category-label"><span className={`category-dot c${index % 5}`}/><b>{label}</b><span>{money(value, currency)}</span></div><Progress value={max > 0 ? value / max * 100 : 0} color={`c${index % 5}`}/></div>; }
function BudgetProgress({ category, spent, allowance, remaining, currency }: { category: string; spent: number; allowance: number; remaining: number; currency: Currency }) { const pct = allowance > 0 ? spent / allowance * 100 : 0; return <div className="mini-budget"><div className="mini-budget-head"><b>{category}</b><span>{money(spent, currency)} <small>of {money(allowance, currency)}</small></span></div><Progress value={pct} color={pct >= 100 ? 'coral' : pct >= 90 ? 'amber' : 'green'}/><small>{remaining >= 0 ? money(remaining, currency) + ' remaining' : money(Math.abs(remaining), currency) + ' over allowance'}</small></div>; }
function GoalMini({ goal, currency }: { goal: Goal; currency: Currency }) { const saved = goalBalance(goal); const p = goal.targetMinor > 0 ? saved / goal.targetMinor * 100 : 0; return <div className="goal-mini"><span className="goal-symbol small-symbol">{goal.icon ?? '✦'}</span><div><b>{goal.title}</b><small>{money(saved, currency)} of {money(goal.targetMinor, currency)}</small><Progress value={p}/></div><strong>{Math.round(p)}%</strong></div>; }
function NaturalReminder({ onParse }: { onParse: (text: string) => void }) { const [value, setValue] = useState(''); return <section className="natural-box"><span className="natural-sparkle"><Sparkles size={19}/></span><div className="natural-copy"><b>Describe a reminder in your own words</b><small>For example, “Pay NPR 10,000 rent on the first of every month at 9 AM.” Ledgerly prepares a draft for you to review.</small></div><form className="natural-form" onSubmit={e => { e.preventDefault(); if (value.trim()) { onParse(value.trim()); setValue(''); } }}><input value={value} onChange={e => setValue(e.target.value)} placeholder="Remind me about…" aria-label="Describe a reminder"/><button className="button primary" disabled={!value.trim()}><Sparkles size={15}/> Make a draft</button></form></section>; }
function renderTrend(transactions: Transaction[], month: string, currency: Currency) { const values = totals(transactions, month); const max = Math.max(values.income, values.expenses, 1); return <div className="cashflow-chart"><div className="chart-legend"><span><i className="legend-income"/> Income</span><span><i className="legend-expense"/> Expenses</span><b>{monthLabel(month)}</b></div><div className="bar-pair"><div className="bar-item"><div className="bar-track"><div className="bar income-bar" style={{ height: `${Math.max(values.income ? 4 : 0, values.income / max * 100)}%` }}/></div><b>{money(values.income, currency)}</b><small>Income</small></div><div className="bar-item"><div className="bar-track"><div className="bar expense-bar" style={{ height: `${Math.max(values.expenses ? 4 : 0, values.expenses / max * 100)}%` }}/></div><b>{money(values.expenses, currency)}</b><small>Expenses</small></div></div>{!values.income && !values.expenses && <p className="chart-empty">No recorded activity in this month yet.</p>}</div>; }
function renderSixMonthTrend(transactions: Transaction[], month: string, currency: Currency) { const months = Array.from({ length: 6 }, (_, i) => { const [y, m] = month.split('-').map(Number); return monthKey(new Date(y, m - 1 - (5 - i), 1)); }); const data = months.map(m => ({ m, ...totals(transactions, m) })); const max = Math.max(...data.flatMap(d => [d.income, d.expenses]), 1); return <div className="six-chart"><div className="chart-legend"><span><i className="legend-income"/> Income</span><span><i className="legend-expense"/> Expenses</span></div><div className="six-bars">{data.map(d => <div className="six-month" key={d.m}><div className="six-pair"><div title={`Income ${money(d.income, currency)}`} className="six-bar income-bar" style={{ height: `${d.income ? Math.max(3, d.income / max * 100) : 0}%` }}/><div title={`Expenses ${money(d.expenses, currency)}`} className="six-bar expense-bar" style={{ height: `${d.expenses ? Math.max(3, d.expenses / max * 100) : 0}%` }}/></div><small>{new Date(`${d.m}-01T12:00:00`).toLocaleDateString(undefined, { month: 'short' })}</small></div>)}</div>{data.every(d => d.income === 0 && d.expenses === 0) && <p className="chart-empty">Record transactions to build a trend.</p>}</div>; }
